INSERT INTO posts (title, slug, excerpt, content, status, author_id, category_id, reading_time, meta_title, meta_description, published_at) VALUES
('مقدمه‌ای بر مکانیک کوانتومی', 'intro-to-quantum-mechanics', 'مکانیک کوانتومی شاخه‌ای از فیزیک است که رفتار ذرات ریز را در مقیاس اتمی و زیراتمی توصیف می‌کند.', '# مقدمه‌ای بر مکانیک کوانتومی\n\nمکانیک کوانتومی یکی از مهم‌ترین دستاوردهای فیزیک در سده بیستم است. برخلاف مکانیک کلاسیک، در این نظریه ذرات رفتاری موجی-ذراتی از خود نشان می‌دهند.\n\n## برهم‌نهی\n\nیکی از مفاهیم کلیدی، «برهم‌نهی» است: ذره می‌تواند تا پیش از اندازه‌گیری در حالات متعددی به طور هم‌زمان موجود باشد.\n\n## درهم‌تنیدگی\n\nدو ذره می‌توانند به گونه‌ای در هم تنیده شوند که وضعیت یکی فوراً بر دیگری تأثیر بگذارد.\n\n## کاربردها\n\nاز لیزرها و ترانزیستورها گرفته تا رایانش کوانتومی، فناوری‌های مدرن بسیاری به درک ما از مکانیک کوانتومی وابسته‌اند.\n\n> این مقاله یک نمونه آموزشی برای نسخه اولیه اَتُمیک است.', 'published', 1, 3, 5, 'مقدمه‌ای بر مکانیک کوانتومی | AtomicMagazine', 'آشنایی با مفاهیم بنیادی مکانیک کوانتومی', datetime('now')),
('ساختار فضا-زمان در کیهان‌شناسی', 'spacetime-cosmology', 'نسبیت عام اینشتین فضا و زمان را به یک شبکه واحد به نام فضا-زمان تبدیل کرد که جرم آن را خم می‌کند.', '# ساختار فضا-زمان در کیهان‌شناسی\n\nدر سال ۱۹۱۵، آلبرت اینشتین با ارائه نسبیت عام، فهم ما از گرانش را دگرگون کرد. او نشان داد که جرم و انرژی، فضا-زمان را خم می‌کنند.\n\n## سیاه‌چاله‌ها\n\nوقتی جرم بسیار زیادی در فضای کوچکی فشرده شود، فضا-زمان تا حدی خم می‌شود که نور نیز نمی‌تواند از آن بگریزد.\n\n## انرژی تاریک\n\nمشاهده انبساط شتاب‌دار کیهان نشان می‌دهد که شاید حدود ۷۰ درصد انرژی جهان به شکل ناشناخته‌ای به نام انرژی تاریک باشد.\n\n> این مقاله در نسخه نمونه بدون منبع رسمی منتشر شده است.', 'published', 1, 2, 6, 'ساختار فضا-زمان در کیهان‌شناسی | AtomicMagazine', 'بررسی مفهوم فضا-زمان و نسبیت عام', datetime('now', '-2 days')),
('ذرات بنیادی و مدل استاندارد', 'particles-standard-model', 'مدل استاندارد نظریه‌ای است که ذرات بنیادی و نیروهای بنیادی را توصیف می‌کند؛ یکی از دقیق‌ترین نظریه‌های تاریخ فیزیک.', '# ذرات بنیادی و مدل استاندارد\n\nمدل استاندارد نقشه‌ای تقریباً کامل از ذرات بنیادی و نیروهای بنیادی است.\n\n## دسته‌بندی ذرات\n\n- **فرمیون‌ها**: ذرات سازنده ماده مانند کوارک‌ها و لپتون‌ها.\n- **بوزون‌ها**: ذرات حامل نیرو مانند فوتون و گلوئون.\n\n## نیروهای بنیادی\n\nمدل استاندارد، نیروهای الکترومغناطیسی، قوی و ضعیف را در یک چارچوب واحد توصیف می‌کند.\n\n## چالش‌های باقی‌مانده\n\nسیاه‌ماده، انرژی تاریک و ترکیب گرانش با نظریه کوانتومی، هنوز سؤالات باز مدل استاندارد هستند.', 'published', 1, 5, 5, 'ذرات بنیادی و مدل استاندارد | AtomicMagazine', 'مدل استاندارد چیست و چگونه ذرات بنیادی را توصیف می‌کند؟', datetime('now', '-4 days')),
('هوش مصنوعی در خدمت علم', 'ai-for-science', 'هوش مصنوعی چگونه در تحلیل داده‌ها، کشف الگوها و شتاب‌دادن به پژوهش‌های علمی نقش ایفا می‌کند؟', '# هوش مصنوعی در خدمت علم\n\nامروز بسیاری از پژوهشگاه‌ها و آزمایشگاه‌ها برای تحلیل حجم عظیمی از داده‌ها از مدل‌های یادگیری ماشین استفاده می‌کنند.\n\n## کشف الگو\n\nالگوریتم‌ها می‌توانند در داده‌های نجومی، زیستی یا فیزیکی الگوهایی بیابند که برای تحلیل دستی دشوارند.\n\n## محدودیت‌ها\n\nبا وجود پیشرفت‌ها، هر مدل نیازمند داده باکیفیت و تفسیر انسانی است.\n\n> این متن نمونه است و برای نمایش ساختار مقاله استفاده می‌شود.', 'published', 1, 4, 4, 'هوش مصنوعی در خدمت علم | AtomicMagazine', 'نگاهی ساده به کاربرد AI در پژوهش‌های علمی', datetime('now', '-1 day')),
('زمان و نسبیت؛ آیا زمان برای همه یکسان می‌گذرد؟', 'time-and-relativity', 'نسبیت اینشتین نشان داد زمان کمیتی مطلق نیست و به چارچوب مرجع وابسته است.', '# زمان و نسبیت\n\nدر زندگی روزمره، زمان را کمیتی ثابت تصور می‌کنیم. اما در نسبیت خاص، گذر زمان برای ناظران مختلف می‌تواند متفاوت باشد.\n\n## اتساع زمان\n\nهرچه سرعت جسمی به سرعت نور نزدیک‌تر شود، زمان برای آن کندتر می‌گذرد.\n\n## اهمیت عملی\n\nسامانه‌هایی مانند GPS برای دقت بالا باید اثرهای نسبیتی را در نظر بگیرند.\n\n> این مقاله نمونه‌ای برای بخش فیزیک و نسبیت است.', 'published', 1, 1, 4, 'زمان و نسبیت | AtomicMagazine', 'چرا زمان در فیزیک مدرن مطلق نیست؟', datetime('now', '-3 days')),
('ماده تاریک؛ چرا جهان سنگین‌تر از چیزی است که می‌بینیم؟', 'dark-matter-basics', 'حرکت کهکشان‌ها و خوشه‌های کهکشانی نشان می‌دهد جرم پنهانی در جهان وجود دارد.', '# ماده تاریک\n\nیکی از معماهای بزرگ کیهان‌شناسی، ماده تاریک است؛ ماده‌ای که نور گسیل نمی‌کند اما اثر گرانشی آن دیده می‌شود.\n\n## سرنخ‌های رصدی\n\nچرخش کهکشان‌ها و عدسی‌گری گرانشی از مهم‌ترین شواهد برای وجود ماده تاریک هستند.\n\n## پرسش باز\n\nهنوز نمی‌دانیم ماده تاریک دقیقاً از چه چیزی ساخته شده است.\n\n> این مقاله به‌صورت نمونه و بدون ارجاع رسمی در seed قرار گرفته است.', 'published', 1, 2, 5, 'ماده تاریک | AtomicMagazine', 'مروری کوتاه بر مفهوم ماده تاریک', datetime('now', '-5 days')),
('مغز چگونه تصمیم می‌گیرد؟', 'brain-and-decision-making', 'علوم شناختی می‌کوشد توضیح دهد مغز چگونه داده‌های حسی را به انتخاب و تصمیم تبدیل می‌کند.', '# مغز چگونه تصمیم می‌گیرد؟\n\nاز ادراک اولیه تا انتخاب نهایی، مغز انسان فرایندی پیچیده و چندلایه را طی می‌کند.\n\n## توجه و فیلتر اطلاعات\n\nمغز همه داده‌های محیط را یکسان پردازش نمی‌کند و بخشی از اطلاعات را برجسته‌تر می‌بیند.\n\n## تصمیم‌گیری\n\nتجربه، حافظه و پیش‌بینی پیامدها، در شکل‌گیری تصمیم نقش دارند.\n\n> این نوشته نمونه‌ای برای گسترش محتوایی دسته‌های آینده است.', 'published', 1, 4, 4, 'مغز چگونه تصمیم می‌گیرد؟ | AtomicMagazine', 'نمونه مقاله‌ای کوتاه درباره علوم شناختی', datetime('now', '-6 days'));
